### 4-2. `src/lib/store.ts` — インメモリストア

```typescript
import { User } from "./types";

// サーバー側・クライアント側両方で動作するインメモリストア
// リセットで消えるが要件通り

let users: User[] = [
  // 初期データ（デモ用）
  { id: "1", name: "劉備", team: "A", rank: "大将軍", createdAt: 1 },
  { id: "2", name: "関羽", team: "A", rank: "丞相",   createdAt: 2 },
  { id: "3", name: "張飛", team: "A", rank: "都督",   createdAt: 3 },
  { id: "4", name: "趙雲", team: "B", rank: "一兵卒", createdAt: 4 },
];

let listeners: Array<() => void> = [];

function emitChange() {
  listeners.forEach((l) => l());
}

export const store = {
  getAll(): User[] {
    return [...users];
  },

  add(user: Omit<User, "id" | "createdAt">): User {
    const newUser: User = {
      ...user,
      id: crypto.randomUUID(),
      createdAt: Date.now(),
    };
    users = [...users, newUser];
    emitChange();
    return newUser;
  },

  subscribe(listener: () => void) {
    listeners.push(listener);
    return () => {
      listeners = listeners.filter((l) => l !== listener);
    };
  },
};
```

