### 4-3. `src/hooks/use-ranking.ts` — カスタムフック

```typescript
"use client";

import { useSyncExternalStore, useCallback } from "react";
import { store } from "@/lib/store";
import { User, RankA, RankB, Team } from "@/lib/types";

export function useRanking() {
  const users = useSyncExternalStore(
    store.subscribe,
    store.getAll,
    store.getAll
  );

  const register = useCallback(
    (name: string, team: Team, rank: RankA | RankB) => {
      store.add({ name, team, rank });
    },
    []
  );

  const teamA = users
    .filter((u) => u.team === "A")
    .sort((a, b) => {
      const order: Record<RankA, number> = {
        大将軍: 1,
        丞相: 2,
        都督: 3,
      };
      return order[a.rank as RankA] - order[b.rank as RankA];
    });

  const teamB = users.filter((u) => u.team === "B");

  return { users, teamA, teamB, register };
}
```

