    md: "w-12 h-12 text-xl",
    lg: "w-16 h-16 text-3xl",
  };

  return (
    <div
      className={`${sizeClasses[size]} flex items-center justify-center rounded-full border-2 shadow-lg transition-transform hover:scale-110`}
      style={{
        borderColor: config.color,
        backgroundColor: `${config.color}20`,
        boxShadow: `0 0 20px ${config.color}40`,
      }}
      title={rank}
    >
      <span className="drop-shadow">{config.icon}</span>
    </div>
  );
}
