### 4-6. `src/components/register-form.tsx` — 登録フォーム

```tsx
"use client";

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { RankA, RankB, Team } from "@/lib/types";

interface RegisterFormProps {
  onRegister: (name: string, team: Team, rank: RankA | RankB) => void;
}

export function RegisterForm({ onRegister }: RegisterFormProps) {
  const [name, setName] = useState("");
  const [team, setTeam] = useState<Team>("A");
  const [rankA, setRankA] = useState<RankA>("大将軍");
  const [rankB] = useState<RankB>("一兵卒");
  const [showSuccess, setShowSuccess] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;
    const rank = team === "A" ? rankA : rankB;
    onRegister(name.trim(), team, rank);
    setName("");
    setShowSuccess(true);
    setTimeout(() => setShowSuccess(false), 2000);
  };

  return (
    <Card className="border-emerald-500/30 bg-gradient-to-br from-gray-900 to-gray-800">
      <CardHeader>
        <CardTitle className="text-center text-xl font-bold text-emerald-400">
          📝 新しい武将を登録
        </CardTitle>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="mb-1 block text-sm text-gray-300">
              名前
            </label>
            <Input
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="例: 趙雲"
              className="border-gray-600 bg-gray-800 text-white placeholder:text-gray-500"
            />
          </div>

          <div>
            <label className="mb-1 block text-sm text-gray-300">
              チーム
            </label>
            <Select
              value={team}
              onValueChange={(v) => setTeam(v as Team)}
            >
              <SelectTrigger className="border-gray-600 bg-gray-800 text-white">
                <SelectValue />
              </SelectTrigger>
              <SelectContent className="border-gray-600 bg-gray-800">
                <SelectItem value="A" className="text-white">
                  A隊（五虎大将軍）
                </SelectItem>
                <SelectItem value="B" className="text-white">
                  B隊（一兵卒）
                </SelectItem>
              </SelectContent>
            </Select>
          </div>

          {team === "A" && (
            <div>
              <label className="mb-1 block text-sm text-gray-300">
                階級
              </label>
              <Select
                value={rankA}
                onValueChange={(v) => setRankA(v as RankA)}
              >
                <SelectTrigger className="border-gray-600 bg-gray-800 text-white">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent className="border-gray-600 bg-gray-800">
                  <SelectItem value="大将軍" className="text-white">
                    👑 大将軍
                  </SelectItem>
                  <SelectItem value="丞相" className="text-white">
                    ⭐ 丞相
                  </SelectItem>
                  <SelectItem value="都督" className="text-white">
                    🛡️ 都督
                  </SelectItem>
                </SelectContent>
              </Select>
            </div>
          )}

          {team === "B" && (
            <p className="text-sm text-gray-400">
              階級: ⚔️ 一兵卒（固定）
            </p>
          )}

          <Button
            type="submit"
            className="w-full bg-emerald-600 text-white transition-all hover:bg-emerald-500 hover:shadow-lg hover:shadow-emerald-500/25"
          >
            登録する
          </Button>

          {showSuccess && (
            <p
              className="text-center text-sm font-medium text-emerald-400"
              style={{ animation: "fadeInUp 0.3s ease-out" }}
            >
              ✅ 登録しました！
            </p>
          )}
        </form>
      </CardContent>
    </Card>
  );
}
```

